import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong();
        long[] req = new long[n];
        for (int i = 0; i < n; i++) req[i] = nextLong();
        Arrays.sort(req);
        int f = (int) nextLong();
        long bestCost = -1;
        int bestId = -1;
        for (int i = 0; i < f; i++) {
            int m = (int) nextLong();
            long[] a = new long[m];
            for (int k = 0; k < m; k++) a[k] = nextLong();
            // Sorted orders: a monotone pointer finds the first marking >= each order.
            int j = 0;
            long cost = 0;
            boolean ok = true;
            for (long x : req) {
                while (j < m && a[j] < x) j++;
                if (j == m) {
                    ok = false;
                    break;
                }
                cost += a[j] - x;
            }
            if (ok && (bestId < 0 || cost < bestCost)) {
                bestCost = cost;
                bestId = i;
            }
        }
        System.out.println(bestId);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	req := make([]int64, n)
	for i := range req {
		fmt.Fscan(in, &req[i])
	}
	sort.Slice(req, func(a, b int) bool { return req[a] < req[b] })
	var f int
	fmt.Fscan(in, &f)
	var bestCost int64 = -1
	bestID := -1
	for i := 0; i < f; i++ {
		var m int
		fmt.Fscan(in, &m)
		a := make([]int64, m)
		for k := range a {
			fmt.Fscan(in, &a[k])
		}
		// Sorted orders: a monotone pointer finds the first marking >= each order.
		j := 0
		var cost int64
		ok := true
		for _, x := range req {
			for j < m && a[j] < x {
				j++
			}
			if j == m {
				ok = false
				break
			}
			cost += a[j] - x
		}
		if ok && (bestID < 0 || cost < bestCost) {
			bestCost, bestID = cost, i
		}
	}
	fmt.Println(bestID)
}
